  "settings.cost_fetch_prompt": {
    "zh-CN": "帮我更新本地模型价格表。单价单位是「元 / 百万 token」，四类分别计价：input（未命中缓存的输入）/ cache_read（命中缓存）/ cache_write（缓存写入）/ output（输出）。\n\n请先用 WebSearch / WebFetch 查这些模型在**官方定价页**的最新单价：\n{models}\n\n再用 Write 把结果写到这个文件：\n{path}\n\n格式（可以先 Read 现有的 config\\pricing.json 当样板）：\n```json\n{\n  \"models\": {\n    \"<模型名>\": { \"input\": 0, \"cache_read\": 0, \"cache_write\": 0, \"output\": 0, \"source_url\": \"<官方定价页 URL>\", \"updated_at\": \"YYYY-MM-DD\" }\n  }\n}\n```\n\n要求：① **不要改 config\\pricing.json** —— 确认由我在设置面板里做；② 沿用旧值的模型保持原来的 source_url / updated_at；③ 查不到的如实说明，不要编数字。\n\n若官方定价页有**峰谷 / 分时价**，照现有 config\\pricing.json 里 `time_windows` 的写法补上：基础四类价填**谷时（缺省）价**，`time_windows` 里填各时段生效的价（含 days / from / to）。",
    "zh-TW": "幫我更新本機模型價格表。單價單位是「元 / 百萬 token」，四類分別計價：input（未命中快取的輸入）/ cache_read（命中快取）/ cache_write（快取寫入）/ output（輸出）。\n\n請先用 WebSearch / WebFetch 查這些模型在**官方定價頁**的最新單價：\n{models}\n\n再用 Write 把結果寫到這個檔案：\n{path}\n\n格式（可以先 Read 現有的 config\\pricing.json 當範本）：\n```json\n{\n  \"models\": {\n    \"<模型名>\": { \"input\": 0, \"cache_read\": 0, \"cache_write\": 0, \"output\": 0, \"source_url\": \"<官方定價頁 URL>\", \"updated_at\": \"YYYY-MM-DD\" }\n  }\n}\n```\n\n要求：① **不要改 config\\pricing.json** —— 確認由我在設定面板裡做；② 沿用舊值的模型保持原本的 source_url / updated_at；③ 查不到的如實說明，不要編數字。\n\n若官方定價頁有**峰谷 / 分時價**，照現有 config\\pricing.json 裡 `time_windows` 的寫法補上：基礎四類價填**谷時（缺省）價**，`time_windows` 裡填各時段生效的價（含 days / from / to）。",
    "ja": "ローカルのモデル価格表を更新してください。単価は「元 / 100万トークン」で、input（キャッシュ未命中）/ cache_read（キャッシュ命中）/ cache_write（キャッシュ書き込み）/ output（出力）の4区分ごとに設定します。\n\nまず WebSearch / WebFetch で、次のモデルの**公式価格ページ**の最新単価を調べてください：\n{models}\n\nその結果を Write でこのファイルに書き出してください：\n{path}\n\n形式（既存の config\\pricing.json を Read して雛形にしても構いません）：\n```json\n{\n  \"models\": {\n    \"<モデル名>\": { \"input\": 0, \"cache_read\": 0, \"cache_write\": 0, \"output\": 0, \"source_url\": \"<公式価格ページのURL>\", \"updated_at\": \"YYYY-MM-DD\" }\n  }\n}\n```\n\n要件：① **config\\pricing.json は変更しない**（確定は設定パネルで行います）。② 旧値をそのまま引き継ぐモデルは source_url / updated_at も元のままにしてください。③ 見つからなければ正直に伝え、数字をでっち上げないでください。\n\n公式ページに**ピーク / オフピーク（時間帯別）価格**がある場合は、既存の config\\pricing.json の `time_windows` の書き方に倣って追加してください：基本の4区分は**オフピーク（既定）価格**、`time_windows` にはその時間帯に適用される価格（days / from / to を含む）を書きます。",
    "ko": "로컬 모델 가격표를 업데이트해 주세요. 단가는 「위안 / 100만 토큰」이고 input(캐시 미스) / cache_read(캐시 적중) / cache_write(캐시 쓰기) / output(출력) 네 가지로 각각 계산합니다.\n\n먼저 WebSearch / WebFetch로 다음 모델의 **공식 가격 페이지** 최신 단가를 확인하세요:\n{models}\n\n그 결과를 Write로 이 파일에 작성하세요:\n{path}\n\n형식(기존 config\\pricing.json을 Read해서 본보기로 삼아도 됩니다):\n```json\n{\n  \"models\": {\n    \"<모델명>\": { \"input\": 0, \"cache_read\": 0, \"cache_write\": 0, \"output\": 0, \"source_url\": \"<공식 가격 페이지 URL>\", \"updated_at\": \"YYYY-MM-DD\" }\n  }\n}\n```\n\n요구 사항: ① **config\\pricing.json은 수정하지 마세요** — 확정은 제가 설정 패널에서 합니다. ② 기존 값을 그대로 쓰는 모델은 원래 source_url / updated_at을 유지하세요. ③ 찾지 못하면 솔직히 알려주고 숫자를 지어내지 마세요.\n\n공식 가격 페이지에 **피크 / 오프피크(시간대별) 가격**이 있으면 기존 config\\pricing.json의 `time_windows` 표기법대로 추가하세요: 기본 네 가지 단가는 **오프피크(기본) 가격**, `time_windows`에는 해당 시간대에 적용되는 가격(days / from / to 포함)을 적습니다.",
    "en": "Please refresh my local model price table. Prices are in CNY per million tokens, billed separately for input (cache miss) / cache_read (cache hit) / cache_write (cache write) / output.\n\nFirst use WebSearch / WebFetch to check the latest official pricing for these models:\n{models}\n\nThen use Write to save the result into this file:\n{path}\n\nFormat (you may Read the existing config\\pricing.json as a template first):\n```json\n{\n  \"models\": {\n    \"<model>\": { \"input\": 0, \"cache_read\": 0, \"cache_write\": 0, \"output\": 0, \"source_url\": \"<official pricing page URL>\", \"updated_at\": \"YYYY-MM-DD\" }\n  }\n}\n```\n\nRules: (1) do **not** edit config\\pricing.json — I confirm it in the settings panel; (2) for models carried over unchanged keep their original source_url / updated_at; (3) if a price cannot be found, say so plainly and never invent numbers.\n\nIf the official page has **peak / off-peak (time-of-day) pricing**, add it the way the existing config\\pricing.json does with `time_windows`: the base four rates are the **off-peak (default)** rates, and each `time_windows` entry carries the rates for that window (with days / from / to).",
  },
